% HS9: generated by bench/corpus/generate.py from the SymPy definition. Do not edit.
% source: Hock & Schittkowski 1981; infinitely many minimizers x=(12k-3, 16k-4)
p.name = 'HS9'; p.family = 'hs'; p.n = 2; p.m = 1;
p.x0 = [0.0; 0.0];
p.xl = [-Inf; -Inf]; p.xu = [Inf; Inf];
