function f = HS9_f(x)
f = sin(pi*x(1)/12).*cos(pi*x(2)/16);
end

function g = HS9_g(x)
g = zeros(2, 1);
g(1) = pi*cos(pi*x(1)/12).*cos(pi*x(2)/16)/12;
g(2) = -pi*sin(pi*x(1)/12).*sin(pi*x(2)/16)/16;
end

function c = HS9_c(x)
c = zeros(1, 1);
c(1) = 4*x(1) - 3*x(2);
end

function J = HS9_J(x)
J = zeros(1, 2);
J(1, 1) = 4;
J(1, 2) = -3;
end
